SELECT count(1)
FROM vm_ar_tags_user_rel
WHERE user_id = #{userId}
  AND tag_id = #{tagId}

SELECT tag_id AS "tagId"
FROM vm_ar_tags_user_rel
WHERE user_id = #{userId}

        SELECT
            tp.id pTypeId, tp.type_name pTypeName, tp.parent_id,
            t.id typeId,t.type_name,t.parent_id,
            a.id,a.ar_view_id,a.tags_type,a.tags_position,a.tags_name,a.tags_desc,a.device_code,a.channel_code,a.coordinate,
        a.resolutionx,a.resolutiony,a.delete_flag,a.creator,a.create_time,a.modifier,a.update_time,a.tenant_id,a.app_ver_code,
        a.industry_code,a.longitude,a.latitude,a.preset_id,case when IFNULL(b.tag_id,0) = 0 then 0 else 1 end markFlag
        from  vm_business_dict_type t LEFT JOIN vm_ar_tags_info a ON t.id = a.tags_type
        left join  vm_business_dict_type tp ON t.parent_id = tp.id
        left join vm_ar_tags_user_rel b on a.id = b.tag_id and b.user_id = #{userName}
        where a.delete_flag = 0

            AND a.ar_view_id = #{arViewId}


            AND a.channel_code = #{channelCode}


        and a.tags_type = #{tagsType}


        and a.tags_name like CONCAT('%', #{tagsName}, '%')


            AND tenant_id = #{tenantId}
            AND industry_code = #{industryCode}


            and t.id not in (390,391,392,393,394,395)
            and a.tag_class = '101'


            AND a.tag_class = #{tagClass}

        ORDER BY tp.id ASC,t.id ASC,
	    CASE WHEN SUBSTRING(a.tags_name, 1, 1) REGEXP '[一-龥]'
           THEN firstPinyin(a.tags_name) ELSE SUBSTRING(a.tags_name, 1, 1)
        END

SELECT id, ar_view_id, tags_type, tags_position, tags_name, tags_desc, device_code, channel_code, coordinate, resolutionx, resolutiony, delete_flag, creator, create_time, modifier, update_time, tenant_id, app_ver_code, industry_code, preset_id FROM vm_ar_tags_info WHERE ar_view_id = #{arViewId}
AND channel_code = #{channelCode}
AND tags_type = #{tagsType}
AND tags_name LIKE concat('%',#{tagsName},'%')
AND tenant_id = #{tenantId} AND industry_code = #{industryCode}

SELECT t1.id, t1.ar_view_id, t1.tags_type, t1.tags_position, t1.tags_name, t1.tags_desc, t1.device_code, t1.channel_code, t1.coordinate, t1.resolutionx, t1.resolutiony, t1.delete_flag, t1.creator, t1.create_time, t1.modifier, t1.update_time, t1.tenant_id, t1.app_ver_code, t1.industry_code, t1.preset_id, t1.tag_pos_type, t1.region_points, t1.extra_json , t1.link_type , t1.label_icon_type, t1.label_icon_id, ig.label_icon_url, t1.longitude, t1.latitude, t1.tag_class, t1.video_file, case when IFNULL(t2.id,0) = 0 then '0' else '1' end markFlag FROM vm_ar_tags_info t1 left join vm_ar_tags_user_rel t2 on t1.id = t2.tag_id AND t2.user_id = #{userName} left join vm_ar_label_icon_gallery ig on t1.label_icon_Id = ig.label_icon_id WHERE t1.delete_flag = 0
AND t1.ar_view_id = #{arViewId}
AND t1.id= #{id}
AND t1.channel_code = #{channelCode}
AND t1.tags_type = #{tagsType}
AND t1.tags_name like CONCAT('%', #{tagsName}, '%')
AND t1.tenant_id = #{tenantId}
AND t1.industry_code = #{industryCode}
AND t1.tag_class = #{tagClass}
and t1.tags_type not in (390,391,392,393,394,395) and t1.tag_class = '101'
AND t1.id IN
#{item}

